### Security & Authentication
**Signature Validation:**
Help Scout signs all requests to your app with HMAC SHA256.
```javascript
const crypto = require('crypto');
function validateSignature(payload, signature, secret) {
const expectedSignature = crypto
.createHmac('sha256', secret)
.update(payload)
.digest('base64');
return crypto.timingSafeEqual(
Buffer.from(signature),
Buffer.from(expectedSignature)
);
}
// Express.js middleware example
app.use('/helpscout-app', (req, res, next) => {
const signature = req.headers['x-helpscout-signature'];
const payload = JSON.stringify(req.body);
if (!validateSignature(payload, signature, process.env.APP_SECRET)) {
return res.status(401).send('Invalid signature');
}
next();
});
```

